def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: set[str] = set()
    history: list[tuple] = []
    rejected: list[int] = []

    def parse_amount(s: str) -> int | None:
        if s and s.isascii() and s.isdigit():
            return int(s)
        return None

    for idx, op in enumerate(ops):
        tokens = op.split(" ")
        verb = tokens[0]

        if verb == "open" and len(tokens) == 3:
            acc = tokens[1]
            amt = parse_amount(tokens[2])
            if amt is not None and acc not in balances:
                balances[acc] = amt
                history.append(("open", acc))
            else:
                rejected.append(idx)

        elif verb == "deposit" and len(tokens) == 3:
            acc = tokens[1]
            amt = parse_amount(tokens[2])
            if amt is not None and amt > 0 and acc in balances:
                balances[acc] += amt
                history.append(("deposit", acc, amt))
            else:
                rejected.append(idx)

        elif verb == "withdraw" and len(tokens) == 3:
            acc = tokens[1]
            amt = parse_amount(tokens[2])
            if (
                amt is not None
                and amt > 0
                and acc in balances
                and acc not in frozen
                and balances[acc] >= amt
            ):
                balances[acc] -= amt
                history.append(("withdraw", acc, amt))
            else:
                rejected.append(idx)

        elif verb == "transfer" and len(tokens) == 4:
            src, dst = tokens[1], tokens[2]
            amt = parse_amount(tokens[3])
            if (
                amt is not None
                and amt > 0
                and src != dst
                and src in balances
                and dst in balances
                and src not in frozen
                and balances[src] >= amt
            ):
                balances[src] -= amt
                balances[dst] += amt
                history.append(("transfer", src, dst, amt))
            else:
                rejected.append(idx)

        elif verb == "freeze" and len(tokens) == 2:
            acc = tokens[1]
            if acc in balances and acc not in frozen:
                frozen.add(acc)
                history.append(("freeze", acc))
            else:
                rejected.append(idx)

        elif verb == "unfreeze" and len(tokens) == 2:
            acc = tokens[1]
            if acc in balances and acc in frozen:
                frozen.remove(acc)
                history.append(("unfreeze", acc))
            else:
                rejected.append(idx)

        elif verb == "undo" and len(tokens) == 1:
            if not history:
                rejected.append(idx)
                continue
            entry = history.pop()
            kind = entry[0]
            if kind == "open":
                acc = entry[1]
                del balances[acc]
                frozen.discard(acc)
            elif kind == "deposit":
                _, acc, amt = entry
                balances[acc] -= amt
            elif kind == "withdraw":
                _, acc, amt = entry
                balances[acc] += amt
            elif kind == "transfer":
                _, src, dst, amt = entry
                balances[src] += amt
                balances[dst] -= amt
            elif kind == "freeze":
                frozen.remove(entry[1])
            elif kind == "unfreeze":
                frozen.add(entry[1])

        else:
            rejected.append(idx)

    return balances, rejected
